static int rproc_reset_rsc_table_on_detach ( struct rproc * rproc ) { struct resource_table * table_ptr ; if ( ! rproc -> table_ptr ) { return 0 ; } table_ptr = rproc -> table_ptr ; rproc -> cached_table = kmemdup ( rproc -> table_ptr , rproc -> table_sz , GFP_KERNEL ) ; if ( ! rproc -> cached_table ) { return - ENOMEM ; } rproc -> table_ptr = rproc -> cached_table ; memcpy ( table_ptr , rproc -> clean_table , rproc -> table_sz ) ; kfree ( rproc -> clean_table ) ; return 0 ; } 